"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2439],{56454:e=>{e.exports=JSON.parse('{"functions":[{"name":"kick","desc":"Kicks a player with the given reason, shown to them verbatim. Performs no\\nprivilege check of its own \u2014 the caller is responsible for authorising the\\naction.","params":[{"name":"player","desc":"player to remove","lua_type":"Player"},{"name":"reason","desc":"message displayed to the kicked player","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":57,"path":"src/Server/Features/Core/AdminService.luau"}},{"name":"check","desc":"Returns whether the player holds `superuser` privileges or higher.\\n\\nCalled by [ProfileService] during profile load to stamp `profile.isAdmin`,\\nwhich is why it must be a cheap synchronous check.","params":[{"name":"player","desc":"player to test","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":73,"path":"src/Server/Features/Core/AdminService.luau"}},{"name":"processMessage","desc":"Records a chat command into the pending audit log and flushes it.\\n\\nThe leading command character is stripped before logging. The\\n[ChatCommand] dispatch that would actually execute the command is currently\\ncommented out, so this only audits.\\n\\nTakes an explicit `self` and calls `self:push_log()`, a name that does not\\nmatch the defined [AdminService.pushLog] \u2014 this path errors if reached.","params":[{"name":"self","desc":"explicit self; called with method syntax","lua_type":"AdminService"},{"name":"player","desc":"who ran the command","lua_type":"Player"},{"name":"payload","desc":"must carry `text` and `userLevel`","lua_type":"table"}],"returns":[],"function_type":"static","source":{"line":94,"path":"src/Server/Features/Core/AdminService.luau"}},{"name":"pushLog","desc":"Flushes the pending command log to the moderation webhook as a batch of\\nDiscord embeds, one per command, carrying the runner\'s name, profile link,\\nheadshot thumbnail, resolved rank and the command text.\\n\\nThe log is cleared **before** the POST is spawned, because\\n`GetUserThumbnailAsync` yields per entry and new commands run during that\\nwindow would otherwise be posted twice. The POST itself is retried up to 3\\ntimes. No-ops on an empty log.","params":[{"name":"_self","desc":"explicit self; unused","lua_type":"AdminService"}],"returns":[],"function_type":"static","source":{"line":141,"path":"src/Server/Features/Core/AdminService.luau"}}],"properties":[],"types":[],"name":"AdminService","desc":"Moderator tooling: privilege checks, kicks, and an audit log of every\\nchat command run, batched to an external webhook.\\n\\nCommands are dispatched by [ChatCommand], whose minimum privilege is raised\\nto `Util.userLevel.moderator` at require time and whose command table is\\nloaded from `ServerScriptService.Data.AdminCommands`.\\n\\n:::caution No commands registered\\n`src/Server/Data/AdminCommands.luau` returns an empty table, so no chat\\ncommands exist today. The dispatch call inside\\n[AdminService.processMessage] is additionally commented out, meaning\\nmessages are logged but never executed as commands. The privilege plumbing\\nis in place; the command set is not.\\n:::\\n\\nNote that [AdminService.check] tests for `superuser`, a stricter bar than the\\n`moderator` level [ChatCommand] is configured with \u2014 so passing `check` and\\nbeing allowed to run a command are two different things.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":27,"path":"src/Server/Features/Core/AdminService.luau"}}')}}]);